// ---------------------------------------------------------------- input variant and check variants
// E01-truncated: two pages of deals, hubspotMaxPages 1. Page 1 holds the 12 open, 6 won and 5 lost deals
// (23 records); page 2 holds the 16 deals created in the window, which are then never read.
const TRUNCATED = {
  id: 'E01-truncated', title: 'Deals read stopped at the page cap', base: 'E01', inputs: { dealPages: 2 }, hubspotMaxPages: 1,
  recorded: one(E01_TEXT, E01_CITES),
  expected: { outcome: 'done', reason: '', modelCalls: 1, check: 'pass', flagsInclude: ['hubspot_truncated'], dataNote: 'CRM read stopped at 23 records; counts may be low' },
};

